# check_uniclubs_recovery.py
"""Check UniClubs cold start and recovery in separate processes with disposable app data.

This command-line acceptance runner is not a registered Streamlit page. Child processes are
test infrastructure; the product does not gain a process manager or background scheduler.
"""
#
# AI CITATION
# Generated by: OpenAI Codex (GPT-6), 2026-11-15
# Last AI change: 2026-11-15, UniClubs Task 7 recovery acceptance
# Based on: User-approved restart/failure checks and existing portable acceptance conventions
# Prompt summary: Verify offline startup and persistent source planning across fresh processes.
# Scope: entire file, except blocks marked "# Written by the team"
# Reviewed by: WeekWise team (pending)
# Changes by the team: none

import argparse
import faulthandler
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

import config
from views import check_demo


ROOT = Path(__file__).resolve().parents[1]
PHASES = ('seed', 'offline', 'malformed', 'older')
MARKER_NAME = '.weekwise-recovery-test'
MARKER_TEXT = 'WeekWise disposable UniClubs recovery test\n'
PROCESS_TIMEOUT_SECONDS = 600


class RecoveryProcesses(unittest.TestCase):
    """Run four independent interpreters against one disposable set of app files."""

    def test_cold_start_and_restarts(self):
        """Require each process to persist and restore plans without shared Python caches."""
        with tempfile.TemporaryDirectory(prefix='weekwise-uniclubs-recovery-') as directory:
            root = Path(directory)
            (root / MARKER_NAME).write_text(MARKER_TEXT, encoding='utf-8')
            for phase in PHASES:
                # A new interpreter is stronger than another browser session in one process.
                result = subprocess.run(
                    [sys.executable, '-m', 'views.check_uniclubs_recovery',
                     '--phase', phase, '--directory', str(root)],
                    cwd=ROOT, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                    text=True, timeout=PROCESS_TIMEOUT_SECONDS, check=False)
                # Stop immediately if setup failed; later phases require its saved state.
                self.assertEqual(result.returncode, 0, f'{phase}:\n' + result.stdout[-12000:])


def run_phase(phase, directory):
    """Isolate every writable path before importing AppTest and the app's source modules."""
    root = Path(directory).resolve()
    marker = root / MARKER_NAME
    if (root / 'data' == config.DATA_DIR.resolve() or not marker.is_file()
            or marker.read_text(encoding='utf-8') != MARKER_TEXT):
        raise ValueError('Recovery phases require the runner-owned disposable directory.')
    check_demo.isolate_paths(root / 'data')
    config.UNICLUBS_FEED_ENABLED = True
    # Defaults bind on import, so the scenario and application are loaded only after isolation.
    from views import uniclubs_recovery_scenario
    uniclubs_recovery_scenario.RecoveryScenario.phase = phase
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(
        uniclubs_recovery_scenario.RecoveryScenario)
    faulthandler.dump_traceback_later(150)
    try:
        result = unittest.TextTestRunner(verbosity=2).run(suite)
    finally:
        faulthandler.cancel_dump_traceback_later()
    return 0 if result.wasSuccessful() else 1


def main():
    """Run all restart phases, or an internal child phase with explicitly isolated paths."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--phase', choices=PHASES, help=argparse.SUPPRESS)
    parser.add_argument('--directory', help=argparse.SUPPRESS)
    arguments = parser.parse_args()
    if arguments.phase:
        if arguments.directory is None:
            parser.error('An internal recovery phase requires its disposable directory.')
        return run_phase(arguments.phase, arguments.directory)
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(RecoveryProcesses)
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    return 0 if result.wasSuccessful() else 1


if __name__ == '__main__':
    raise SystemExit(main())
